#include <stdio.h>

int fact(int n) {
    int f = 1;
    for (int i = 2; i <= n; i++) {
        f *= i;
    }
    return f;
}

int main() {
    for (int n = 0; n < 5; n++) {
        for (int k = 0; k <= n; k++) {
            printf("%d ", fact(n) / (fact(k) * fact(n - k)));
        }
        printf("\n");
    }
    return 0;
}

