#include <stdio.h>

int main() {
    int triangle[5][5] = {{0}};
    for (int n = 0; n < 5; n++) {
        triangle[n][0] = 1;
        for (int k = 1; k <= n; k++) {
            triangle[n][k] = triangle[n - 1][k - 1] + (k < n ? triangle[n - 1][k] : 0);
        }
        for (int k = 0; k <= n; k++) {
            printf("%d ", triangle[n][k]);
        }
        printf("\n");
    }
    return 0;
}
